  `area_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '[地区名] 冗余的地区名称',
  `ent_type_id` bigint(0) NOT NULL COMMENT '[企业类型ID] 关联ent_type_dict.id',
