DROP TABLE IF EXISTS `punish_notice`;
CREATE TABLE `punish_notice`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '[主键ID]',
  `notice_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '[处罚通知书编号] 唯一编号',
  `punish_review_id` bigint(0) NOT NULL COMMENT '[处罚复审台账ID] 关联punish_review_ledger.id，唯一',
  `ent_pay_record_id` bigint(0) NULL DEFAULT NULL COMMENT '[企业缴费记录表id]',
