  `receive_time` datetime(0) NULL DEFAULT NULL COMMENT '[送达时间]',
  `pay_deadline` datetime(0) NOT NULL COMMENT '[缴款期限]',
  `receive_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '[送达状态] 如：未送达/已送达/拒收',
  `actual_punish_amt` decimal(10, 2) NOT NULL COMMENT '[实际处罚金额] 单位：元',
  `decision_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '[处罚决定书原件内容] 富文本',
  `creator` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[创建人] 关联park_user.id',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '[创建时间] 记录创建时间',
  `updater` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[更新人] 关联park_user.id',
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '[更新时间] 记录最后更新时间',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '[删除标识] 如:0-未删除/1-已删除',
  `tenant_id` bigint(0) NOT NULL DEFAULT 0 COMMENT '[租户ID]',
  `ext_common1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[通用扩展字段1]',
  `ext_common2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[通用扩展字段2]',
  `ext_common3` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[通用扩展字段3]',
  `ext_common4` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[通用扩展字段4]',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_notice_code`(`notice_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '处罚通知书表' ROW_FORMAT = Dynamic;

