  `illegal_level_id` bigint(0) NOT NULL COMMENT '[违规等级ID] 关联illegal_level_dict.id',
  `ent_rectify_record_id` bigint(0) NULL DEFAULT NULL COMMENT '[企业整改记录id]',
  `punish_notice_id` bigint(0) NULL DEFAULT NULL COMMENT '[处罚通知书id]',
  `law_ledger_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[执法复审台账编号] 关联law_review_ledger.ledger_code',
  `evidence_url` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[违规证据链接] JSON字符串格式，可多链接',
  `draft_punish_amt` decimal(10, 2) NOT NULL COMMENT '[草拟处罚金额] 单位：元',
  `legal_basis` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '[处罚法律依据]',
  `review_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '[复审状态] 如：待复审/已下发/已撤销',
  `review_by` bigint(0) NULL DEFAULT NULL COMMENT '[复审人] 关联park_user.id',
  `cancel_reason_id` bigint(0) NULL DEFAULT NULL COMMENT '[撤销原因ID] 关联cancel_reason_dict.id，仅已撤销状态赋值',
  `draft_time` datetime(0) NOT NULL COMMENT '[草拟时间]',
  `review_time` datetime(0) NULL DEFAULT NULL COMMENT '[复审时间]',
  `cancel_time` datetime(0) NULL DEFAULT NULL COMMENT '[撤销时间]',
  `creator` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[创建人] 关联park_user.id',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '[创建时间] 记录创建时间',
  `updater` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[更新人] 关联park_user.id',
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '[更新时间] 记录最后更新时间',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '[删除标识] 如:0-未删除/1-已删除',
  `tenant_id` bigint(0) NOT NULL DEFAULT 0 COMMENT '[租户ID]',
  `ext_common1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[通用扩展字段1]',
  `ext_common2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[通用扩展字段2]',
  `ext_common3` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[通用扩展字段3]',
  `ext_common4` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[通用扩展字段4]',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '处罚通知书复审台账表' ROW_FORMAT = Dynamic;

