INSERT INTO `punish_notice` VALUES (23, 'PNTC202603256b518b51', 18, NULL, '2026-03-25 16:37:01', NULL, '2026-04-24 16:37:00', '未送达', 916.00, '<div style=\"font-family:SimSun;font-size:16px;line-height:28px\">\n\n<div style=\"text-align:center;font-size:22px;font-weight:bold\">\n泉州市丰泽区市场监督管理局\n</div>\n\n<div style=\"text-align:center;font-size:20px;font-weight:bold;margin-top:10px\">\n行政处罚决定书\n</div>\n\n<div style=\"text-align:center;margin-top:10px\">\n泉州市监罚〔2026〕PNTC202603256b518b51号\n</div>\n\n<br/>\n\n<p>当事人：泉州师范学院校园餐饮服务中心</p>\n<p>统一社会信用代码/注册号：ENT20250312004</p>\n<p>地址：泉州市丰泽区东海大街398号泉州师范学院内</p>\n<p>法定代表人/负责人：张丽华 联系电话：0595-22896704</p>\n\n<p style=\"text-indent:2em\">\n经查，你（单位）在校园餐饮后厨经营过程中，存在从业人员在工作区吸烟。上述事实有整改通知书为证。\n</p>\n\n<p style=\"text-indent:2em\">\n你（单位）的上述行为违反了《中华人民共和国食品安全法》第三十三条、\n《餐饮服务食品安全操作规范》第十六条等相关规定，已构成违法。\n</p>\n\n<p style=\"text-indent:2em\">\n依据《中华人民共和国行政处罚法》第五十七条、《中华人民共和国食品安全法》第一百二十六条第一款第（三）项的规定，决定对你（单位）作出如下行政处罚：\n<br/>1. 警告；\n<br/>2. 罚款人民币916.00元（大写：玖佰壹拾陆）。\n</p>\n\n<p style=\"text-indent:2em\">\n限你（单位）自收到本决定书之日起十五日内，将罚款缴至泉州丰泽区农业银行（账户：3500123456789012）。\n逾期不缴纳罚款的，依据《中华人民共和国行政处罚法》第七十二条第一款第（一）项的规定，每日按罚款数额的百分之三加处罚款。\n</p>\n\n<p style=\"text-indent:2em\">\n如对本处罚决定不服，可以自收到本决定书之日起六十日内向泉州市市场监督管理局行政复议科申请行政复议；\n也可以在六个月内依法向泉州市丰泽区人民法院提起行政诉讼。复议、诉讼期间，本行政处罚决定不停止执行。\n</p>\n\n<p>联系人：张三和 联系电话：0591-12372923</p>\n<p>联系地址：泉州市丰泽区东街路88号</p>\n\n<br/>\n<div style=\"text-align:right\">泉州市丰泽区市场监督管理局</div>\n<div style=\"text-align:right\">(印 章)</div>\n<div style=\"text-align:right;margin-top:10px\">2026 年 3 月 25 日</div>\n\n<br/><br/>\n<p>本文书一式三份，两份送达，一份归档，存档于市场监督管理局档案室。</p>\n\n</div>\n', '1', '2026-03-25 16:37:01', '1', '2026-03-25 16:37:01', b'0', 1, NULL, NULL, NULL, NULL);
