INSERT INTO `rectify_notice` VALUES (64, 'RNTC20260325c107c486', 62, '2026-03-25 16:36:13', '2026-04-04', '未送达', NULL, '<div style=\"font-family:SimSun;font-size:16px;line-height:30px\">\n\n<div style=\"text-align:center;font-size:22px;font-weight:bold\">\n泉州市市场监督管理局\n</div>\n\n<div style=\"text-align:center;font-size:20px;font-weight:bold;margin-top:10px\">\n责令改正通知书\n</div>\n\n<div style=\"text-align:center;margin-top:10px\">\n泉州市监责改〔2026〕RNTC20260325c107c486号\n</div>\n\n<br/>\n\n<p>泉州市丰泽区育才餐饮管理有限公司：</p>\n\n<p style=\"text-indent:2em\">\n经查，你（单位）在校园餐饮后厨操作过程中，\n存在从业人员未按规定佩戴口罩的行为，\n违反了《中华人民共和国食品安全法》第四十七条\n（食品生产经营者应当建立并执行从业人员健康管理制度）、\n《餐饮服务食品安全操作规范》第十六条\n（从业人员个人卫生要求）等相关规定。\n</p>\n\n<p style=\"text-indent:2em\">\n依据《中华人民共和国行政处罚法》第二十八条、\n《中华人民共和国食品安全法》第一百二十六条的规定，\n现责令你（单位）在 2026年4月4日 前改正。\n</p>\n\n<p style=\"text-indent:2em\">\n（改正内容及要求：立即组织后厨从业人员开展食品安全操作规范培训，\n严格落实穿戴工作帽、口罩等个人卫生要求。）\n</p>\n\n<p style=\"text-indent:2em\">\n（逾期不改的，本局将依据《中华人民共和国食品安全法》第一百二十六条的规定，\n依法给予行政处罚；情节严重的，责令停产停业，直至吊销许可证。）\n</p>\n\n<p style=\"text-indent:2em\">\n如对本责令改正决定不服，可以自收到本通知书之日起六十日内向\n泉州市人民政府申请行政复议；\n也可以在六个月内依法向泉州市鲤城区人民法院提起行政诉讼。\n</p>\n\n<br/>\n\n<p>\n联系人：黄志明\n&nbsp;&nbsp;&nbsp;&nbsp;\n联系电话：0595-22896705\n</p>\n\n<p>\n联系地址：泉州市丰泽区城东街道安吉路67号\n</p>\n\n<br/><br/>\n\n<div style=\"text-align:right\">\n泉州市市场监督管理局\n</div>\n\n<div style=\"text-align:right;margin-top:10px\">\n2026 年 3 月 25 日\n</div>\n\n<br/><br/>\n\n<p>\n本文书一式三份，两份送达，一份归档，存档于市场监督管理局档案室。\n</p>\n\n</div>\n', '1', '1', '2026-03-25 16:36:13', '2026-03-25 16:36:13', b'0', 1, NULL, NULL, NULL, NULL);
INSERT INTO `rectify_notice` VALUES (65, 'RNTC20260325c0b9a885', 63, '2026-03-25 16:36:15', '2026-04-04', '未送达', NULL, '<div style=\"font-family:SimSun;font-size:16px;line-height:30px\">\n\n<div style=\"text-align:center;font-size:22px;font-weight:bold\">\n泉州市市场监督管理局\n</div>\n\n<div style=\"text-align:center;font-size:20px;font-weight:bold;margin-top:10px\">\n责令改正通知书\n</div>\n\n<div style=\"text-align:center;margin-top:10px\">\n泉州市监责改〔2026〕RNTC20260325c0b9a885号\n</div>\n\n<br/>\n\n<p>泉州丰泽区荣茂餐饮服务有限公司：</p>\n\n<p style=\"text-indent:2em\">\n经查，你（单位）在校园餐饮后厨操作过程中，\n存在从业人员未穿厨师服的行为，\n违反了《中华人民共和国食品安全法》第四十七条\n（食品生产经营者应当建立并执行从业人员健康管理制度）、\n《餐饮服务食品安全操作规范》第十六条\n（从业人员个人卫生要求）等相关规定。\n</p>\n\n<p style=\"text-indent:2em\">\n依据《中华人民共和国行政处罚法》第二十八条、\n《中华人民共和国食品安全法》第一百二十六条的规定，\n现责令你（单位）在 2026年4月4日 前改正。\n</p>\n\n<p style=\"text-indent:2em\">\n（改正内容及要求：立即组织后厨从业人员开展食品安全操作规范培训，\n严格落实穿戴工作帽、口罩等个人卫生要求。）\n</p>\n\n<p style=\"text-indent:2em\">\n（逾期不改的，本局将依据《中华人民共和国食品安全法》第一百二十六条的规定，\n依法给予行政处罚；情节严重的，责令停产停业，直至吊销许可证。）\n</p>\n\n<p style=\"text-indent:2em\">\n如对本责令改正决定不服，可以自收到本通知书之日起六十日内向\n泉州市人民政府申请行政复议；\n也可以在六个月内依法向泉州市鲤城区人民法院提起行政诉讼。\n</p>\n\n<br/>\n\n<p>\n联系人：李美珍\n&nbsp;&nbsp;&nbsp;&nbsp;\n联系电话：0595-22896708\n</p>\n\n<p>\n联系地址：泉州市丰泽区华大街道城华北路269号华侨大学内\n</p>\n\n<br/><br/>\n\n<div style=\"text-align:right\">\n泉州市市场监督管理局\n</div>\n\n<div style=\"text-align:right;margin-top:10px\">\n2026 年 3 月 25 日\n</div>\n\n<br/><br/>\n\n<p>\n本文书一式三份，两份送达，一份归档，存档于市场监督管理局档案室。\n</p>\n\n</div>\n', '1', '1', '2026-03-25 16:36:15', '2026-03-25 16:36:15', b'0', 1, NULL, NULL, NULL, NULL);
